,"name":"updateMaxBridgedInSupply","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"maxBridgedOutSupply_","type":"uint256"}],"name":"updateMaxBridgedOutSupply","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"newMaxTotalSupply_","type":"uint256"}],"name":"updateMaxTotalSupply","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"contract IProxyOFT","name":"newProxyOFT_","type":"address"}],"name":"updateProxyOFT","outputs":[],"stateMutability":"nonpayable","type":"function"}],"devdoc":{"events":{"Approval(address,address,uint256)":{"details":"Emitted when the allowance of a `spender` for an `owner` is set by a call to {approve}. `value` is the new allowance."},"Initialized(uint8)":{"details":"Triggered when the contract has been initialized or reinitialized."},"Transfer(address,address,uint256)":{"details":"Emitted when `value` tokens are moved from one account (`from`) to another (`to`). Note that `value` may be zero."}},"kind":"dev","methods":{"bridgedInSupply()":{"details":"The supply is calculated using `MAX(totalBridgedIn - totalBridgedOut, 0)`"},"bridgedOutSupply()":{"details":"The supply is calculated using `MAX(totalBridgedOut - totalBridgedIn, 0)`"},"burn(address,uint256)":{"params":{"amount_":"The amount to burn","from_":"The account to burn from"}},"mint(address,uint256)":{"params":{"amount_":"The amount to mint","to_":"The account to mint to"}},"seize(address,address,uint256)":{"details":"Same as _transfer","params":{"amount_":"The amount to seize","to_":"The beneficiary account"}},"transfer(address,uint256)":{"details":"Moves `amount` tokens from the caller's account to `recipient`. Returns a boolean value indicating whether the operation succeeded. Emits a {Transfer} event."},"transferFrom(address,address,uint256)":{"details":"Moves `amount` tokens from `sender` to `recipient` using the allowance mec